"""Brute-force solvers written from the problem definitions."""

from __future__ import annotations

import itertools


def solve_three_sat(instance):
    """Return True iff the 3-SAT instance is satisfiable (brute force)."""
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        # variable v (1..m) is true iff bits[v-1]
        if all(
            any(bits[abs(lit) - 1] == (lit > 0) for lit in clause)
            for clause in clauses
        ):
            return True
    return False


def _max_clique_size(n, adj):
    """Exact maximum clique size via simple branch and bound."""
    best = 0

    def expand(candidates, size):
        nonlocal best
        if size + len(candidates) <= best:
            return
        if not candidates:
            if size > best:
                best = size
            return
        # Bound: cannot beat best with remaining candidates.
        while candidates:
            if size + len(candidates) <= best:
                return
            v = candidates.pop()
            expand([u for u in candidates if adj[v][u]], size + 1)

    expand(list(range(n)), 0)
    return best


def solve_clique(instance):
    """Return True iff the graph has a clique of at least k vertices."""
    n = instance["n"]
    k = instance["k"]
    if k <= 0:
        return True
    if k > n:
        return False
    adj = [[False] * n for _ in range(n)]
    for u, v in instance["edges"]:
        adj[u][v] = True
        adj[v][u] = True
    return _max_clique_size(n, adj) >= k
EOF
